1	import { Router, type IRouter } from "express";
2	import { desc, eq, or, and, inArray } from "drizzle-orm";
3	import { db, messagesTable, courtsTable, notificationsTable, facilitiesTable, userProfilesTable, bookingsTable } from "@workspace/db";
4	import { requireAuth } from "../lib/auth";
5	import { getAuth, clerkClient } from "@clerk/express";
6	
7	const router: IRouter = Router();
8	
9	function formatMsg(r: typeof messagesTable.$inferSelect) {
10	  return { ...r, createdAt: r.createdAt.toISOString() };
11	}
12	
13	// GET /messages/inbox  — all threads the authenticated user participated in
14	router.get("/messages/inbox", requireAuth, async (req, res): Promise<void> => {
15	  const { userId } = getAuth(req);
16	
17	  const rows = await db
18	    .select()
19	    .from(messagesTable)
20	    .where(or(eq(messagesTable.senderUserId, userId!), eq(messagesTable.recipientUserId, userId!)))
21	    .orderBy(desc(messagesTable.createdAt));
22	
23	  // Group by courtId — each court is one thread
24	  const threadMap = new Map<number, typeof rows>();
25	  for (const row of rows) {
26	    if (!threadMap.has(row.courtId)) threadMap.set(row.courtId, []);
27	    threadMap.get(row.courtId)!.push(row);
28	  }
29	
30	  const courtIds = [...threadMap.keys()];
31	  const courts = courtIds.length
32	    ? await db.select({ id: courtsTable.id, name: courtsTable.name }).from(courtsTable).where(inArray(courtsTable.id, courtIds))
33	    : [];
34	  const courtNameMap = new Map(courts.map(c => [c.id, c.name]));
35	
36	  const threads = [...threadMap.entries()].map(([courtId, msgs]) => ({
37	    courtId,
38	    courtName: courtNameMap.get(courtId) ?? `Kortas #${courtId}`,
39	    lastMessage: formatMsg(msgs[0]),
40	    unread: 0,
41	  }));
42	
43	  res.json(threads);
44	});
45	
46	// GET /messages/owner-inbox  — all threads across the authenticated owner's courts
47	router.get("/messages/owner-inbox", requireAuth, async (req, res): Promise<void> => {
48	  const { userId: ownerUserId } = getAuth(req);
49	
50	  const ownedCourts = await db
51	    .select({ id: courtsTable.id, name: courtsTable.name })
52	    .from(courtsTable)
53	    .innerJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
54	    .where(eq(facilitiesTable.ownerUserId, ownerUserId!));
55	
56	  if (ownedCourts.length === 0) { res.json([]); return; }
57	
58	  const courtIds = ownedCourts.map(c => c.id);
59	  const courtNameMap = new Map(ownedCourts.map(c => [c.id, c.name]));
60	
61	  const rows = await db
62	    .select()
63	    .from(messagesTable)
64	    .where(inArray(messagesTable.courtId, courtIds))
65	    .orderBy(desc(messagesTable.createdAt));
66	
67	  // Group by courtId + the non-owner userId (thread key)
68	  const threadMap = new Map<string, typeof rows>();
69	  for (const row of rows) {
70	    const userSide = row.senderUserId === ownerUserId ? row.recipientUserId : row.senderUserId;
71	    const key = `${row.courtId}__${userSide}`;
72	    if (!threadMap.has(key)) threadMap.set(key, []);
73	    threadMap.get(key)!.push(row);
74	  }
75	
76	  const rawThreads = [...threadMap.entries()].map(([key, msgs]) => {
77	    const [courtIdStr, threadUserId] = key.split("__");
78	    const courtId = Number(courtIdStr);
79	    const first = msgs[0];
80	    const userSide = first.senderUserId === ownerUserId ? first : msgs.find(m => m.senderUserId !== ownerUserId) ?? first;
81	    return {
82	      courtId,
83	      courtName: courtNameMap.get(courtId) ?? `Kortas #${courtId}`,
84	      threadUserId,
85	      threadUserName: userSide.senderUserId !== ownerUserId ? userSide.senderName : (userSide.recipientEmail ?? "Vartotojas"),
86	      lastMessage: formatMsg(first),
87	      unread: 0,
88	    };
89	  });
90	
91	  // Fetch profile image URLs for all thread users
92	  const threadUserIds = [...new Set(rawThreads.map(t => t.threadUserId))];
93	  const profileRows = threadUserIds.length
94	    ? await db.select({ userId: userProfilesTable.userId, imageUrl: userProfilesTable.imageUrl })
95	        .from(userProfilesTable)
96	        .where(inArray(userProfilesTable.userId, threadUserIds))
97	    : [];
98	  const imageMap = new Map(profileRows.map(p => [p.userId, p.imageUrl]));
99	
100	  // Fetch most-recent booking per (courtId, threadUserId) for booking context
101	  const bookingRows = rawThreads.length
102	    ? await db.select({
103	        id: bookingsTable.id,
104	        courtId: bookingsTable.courtId,
105	        bookerUserId: bookingsTable.bookerUserId,
106	        date: bookingsTable.date,
107	        startTime: bookingsTable.startTime,
108	        endTime: bookingsTable.endTime,
109	        status: bookingsTable.status,
110	      })
111	        .from(bookingsTable)
112	        .where(
113	          and(
114	            inArray(bookingsTable.courtId, courtIds),
115	            inArray(bookingsTable.bookerUserId, threadUserIds as [string, ...string[]]),
116	          ),
117	        )
118	        .orderBy(desc(bookingsTable.date))
119	    : [];
120	
121	  // Build a map: `${courtId}__${userId}` → most recent booking
122	  const bookingMap = new Map<string, typeof bookingRows[0]>();
123	  for (const b of bookingRows) {
124	    const key = `${b.courtId}__${b.bookerUserId}`;
125	    if (!bookingMap.has(key)) bookingMap.set(key, b);
126	  }
127	
128	  const threads = rawThreads.map(t => {
129	    const bk = bookingMap.get(`${t.courtId}__${t.threadUserId}`);
130	    return {
131	      ...t,
132	      threadUserImageUrl: imageMap.get(t.threadUserId) ?? null,
133	      latestBooking: bk
134	        ? {
135	            id: bk.id,
136	            date: bk.date,
137	            startTime: bk.startTime,
138	            endTime: bk.endTime,
139	            status: bk.status,
140	          }
141	        : null,
142	    };
143	  });
144	
145	  res.json(threads);
146	});
147	
148	// GET /courts/:id/messages  — all messages in a thread the caller is part of.
149	// Optional ?userId=… narrows to a single owner↔customer thread; only the court
150	// owner is allowed to filter this way (otherwise it would expose other users'
151	// messages on the same court).
152	router.get("/courts/:id/messages", requireAuth, async (req, res): Promise<void> => {
153	  const courtId = Number(req.params.id);
154	  const { userId } = getAuth(req);
155	  if (Number.isNaN(courtId)) {
156	    res.status(400).json({ error: "courtId is required" });
157	    return;
158	  }
159	
160	  const threadUserIdRaw = req.query.userId;
161	  const threadUserId = typeof threadUserIdRaw === "string" ? threadUserIdRaw : undefined;
162	
163	  const [court] = await db.select({ ownerUserId: facilitiesTable.ownerUserId })
164	    .from(courtsTable)
165	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
166	    .where(eq(courtsTable.id, courtId));
167	  const isOwner = !!court && court.ownerUserId === userId;
168	
169	  // Owner asking for a specific thread → only messages between owner and that customer.
170	  if (isOwner && threadUserId) {
171	    const rows = await db
172	      .select()
173	      .from(messagesTable)
174	      .where(and(
175	        eq(messagesTable.courtId, courtId),
176	        or(
177	          and(eq(messagesTable.senderUserId, userId!), eq(messagesTable.recipientUserId, threadUserId)),
178	          and(eq(messagesTable.senderUserId, threadUserId), eq(messagesTable.recipientUserId, userId!)),
179	        ),
180	      ))
181	      .orderBy(messagesTable.createdAt);
182	    res.json(rows.map(formatMsg));
183	    return;
184	  }
185	
186	  // Default: only messages where caller is sender or recipient.
187	  const rows = await db
188	    .select()
189	    .from(messagesTable)
190	    .where(and(eq(messagesTable.courtId, courtId), or(eq(messagesTable.senderUserId, userId!), eq(messagesTable.recipientUserId, userId!))))
191	    .orderBy(messagesTable.createdAt);
192	
193	  res.json(rows.map(formatMsg));
194	});
195	
196	// POST /courts/:id/messages  — send a message (user→court or owner→user)
197	router.post("/courts/:id/messages", requireAuth, async (req, res): Promise<void> => {
198	  const courtId = Number(req.params.id);
199	  const { userId: senderUserId } = getAuth(req);
200	  const { body, threadUserId } = req.body ?? {};
201	  if (Number.isNaN(courtId) || !body) {
202	    res.status(400).json({ error: "Missing required fields" });
203	    return;
204	  }
205	
206	  // Resolve sender identity from Clerk — never trust client-supplied name/email.
207	  let senderName = "Vartotojas";
208	  let senderEmail = "";
209	  try {
210	    const clerkUser = await clerkClient.users.getUser(senderUserId!);
211	    senderName = [clerkUser.firstName, clerkUser.lastName].filter(Boolean).join(" ") || "Vartotojas";
212	    senderEmail = clerkUser.emailAddresses[0]?.emailAddress ?? "";
213	  } catch {
214	    // Clerk unavailable (e.g. no CLERK_SECRET_KEY in dev) — proceed with defaults.
215	  }
216	
217	  const [court] = await db.select().from(courtsTable).where(eq(courtsTable.id, courtId));
218	  if (!court) { res.status(404).json({ error: "Court not found" }); return; }
219	
220	  const [msgFacility] = await db.select({ ownerUserId: facilitiesTable.ownerUserId, email: facilitiesTable.email })
221	    .from(facilitiesTable)
222	    .where(eq(facilitiesTable.id, court.facilityId));
223	
224	  const isOwner = msgFacility?.ownerUserId === senderUserId;
225	
226	  // When owner replies, threadUserId tells us who they're replying to
227	  let recipientUserId: string | null = null;
228	  let recipientEmail: string | null = null;
229	
230	  if (isOwner && threadUserId) {
231	    // Owner replying to a user — find the user's email from prior messages
232	    const [prior] = await db
233	      .select()
234	      .from(messagesTable)
235	      .where(and(eq(messagesTable.courtId, courtId), eq(messagesTable.senderUserId, threadUserId)));
236	    recipientUserId = threadUserId;
237	    recipientEmail = prior?.senderEmail ?? null;
238	  } else {
239	    recipientUserId = msgFacility?.ownerUserId ?? null;
240	    recipientEmail = msgFacility?.email ?? null;
241	  }
242	
243	  const [message] = await db.insert(messagesTable).values({
244	    courtId,
245	    senderUserId: senderUserId!,
246	    senderName,
247	    senderEmail,
248	    recipientUserId,
249	    recipientEmail,
250	    subject: isOwner ? "Re: Žinutė nuo savininko" : "Žinutė kortui",
251	    body,
252	  }).returning();
253	
254	  // Fire notification for the recipient
255	  if (recipientUserId) {
256	    await db.insert(notificationsTable).values({
257	      userId: recipientUserId,
258	      type: "message",
259	      title: isOwner ? `Atsakymas nuo savininko — ${court.name}` : `Nauja žinutė nuo ${senderName}`,
260	      body: body.length > 100 ? body.slice(0, 97) + "…" : body,
261	      link: isOwner ? "/profile" : `/courts/${courtId}`,
262	    }).catch(() => {});
263	  }
264	
265	  res.status(201).json(formatMsg(message));
266	});
267	
268	export default router;
