1	import { useState, useEffect, useRef, useMemo } from "react";
2	import { useParams } from "wouter";
3	import { useUser } from "@clerk/react";
4	import { format, parseISO } from "date-fns";
5	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
6	import { customFetch } from "@workspace/api-client-react";
7	import { OwnerLayout } from "@/components/owner-layout";
8	import { Button } from "@/components/ui/button";
9	import { Skeleton } from "@/components/ui/skeleton";
10	import { Textarea } from "@/components/ui/textarea";
11	import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
12	import { Badge } from "@/components/ui/badge";
13	import {
14	  ArrowLeft,
15	  Calendar,
16	  Loader2,
17	  MessageSquare,
18	  Send,
19	} from "lucide-react";
