21	const BASE_URL = import.meta.env.BASE_URL.replace(/\/$/, "");
22	const API_URL = `${BASE_URL}/api`;
23	
24	interface FacilityData {
25	  id: number;
26	  name: string;
27	  ownerUserId?: string;
28	}
29	
30	interface CourtSummary {
31	  id: number;
32	  facilityId?: number | null;
33	}
34	
35	function useIsDesktop() {
36	  const [isDesktop, setIsDesktop] = useState(() =>
37	    typeof window === "undefined"
38	      ? true
39	      : window.matchMedia("(min-width: 768px)").matches,
40	  );
41	  useEffect(() => {
42	    if (typeof window === "undefined") return;
43	    const mq = window.matchMedia("(min-width: 768px)");
44	    const onChange = (e: MediaQueryListEvent) => setIsDesktop(e.matches);
45	    mq.addEventListener("change", onChange);
46	    return () => mq.removeEventListener("change", onChange);
47	  }, []);
48	  return isDesktop;
49	}
50	
51	interface LatestBooking {
52	  id: number;
53	  date: string;
54	  startTime: string;
55	  endTime: string;
56	  status: string;
57	}
58	
59	interface OwnerThread {
60	  courtId: number;
61	  courtName: string;
62	  threadUserId: string;
63	  threadUserName: string;
64	  threadUserImageUrl: string | null;
65	  latestBooking: LatestBooking | null;
66	  lastMessage: { body: string; senderUserId: string; createdAt: string };
67	}
68	
69	interface OwnerMsg {
70	  id: number;
71	  senderUserId: string;
72	  senderName: string;
73	  body: string;
74	  createdAt: string;
75	}
76	
77	function threadKey(t: OwnerThread) {
78	  return `${t.courtId}__${t.threadUserId}`;
79	}
80	
81	function messagesQueryKey(courtId: number, threadUserId: string) {
82	  return ["owner-court-messages", courtId, threadUserId] as const;
83	}
84	
85	function ThreadList({
86	  threads,
87	  selectedKey,
88	  loading,
89	  onSelect,
90	}: {
91	  threads: OwnerThread[];
92	  selectedKey: string | null;
93	  loading: boolean;
94	  onSelect: (t: OwnerThread) => void;
95	}) {
96	  if (loading) {
97	    return (
98	      <div className="p-3 space-y-2">
99	        {Array.from({ length: 5 }).map((_, i) => (
100	          <Skeleton key={i} className="h-16 w-full rounded-lg" />
101	        ))}
102	      </div>
103	    );
104	  }
105	  if (threads.length === 0) {
106	    return (
107	      <div className="flex flex-col items-center justify-center h-full text-muted-foreground text-sm gap-2 p-6 text-center">
108	        <MessageSquare className="w-10 h-10 opacity-20" />
109	        <p className="font-medium">Dar nėra žinučių.</p>
110	        <p className="text-xs">
111	          Kai klientai parašys apie šio objekto aikšteles, pokalbiai atsiras čia.
112	        </p>
113	      </div>
114	    );
115	  }
116	  return (
117	    <ul className="divide-y">
118	      {threads.map((t) => {
119	        const key = threadKey(t);
120	        const active = key === selectedKey;
121	        const last = t.lastMessage;
122	        return (
123	          <li key={key}>
124	            <button
125	              type="button"
126	              onClick={() => onSelect(t)}
127	              className={`w-full text-left px-4 py-3 transition-colors flex gap-3 ${
128	                active ? "bg-primary/10" : "hover:bg-muted/60"
129	              }`}
130	            >
131	              <Avatar className="h-10 w-10 shrink-0 mt-0.5">
132	                {t.threadUserImageUrl && <AvatarImage src={t.threadUserImageUrl} alt={t.threadUserName} />}
133	                <AvatarFallback className="bg-primary/15 text-primary font-semibold text-xs">
134	                  {t.threadUserName.split(" ").map((n: string) => n[0]).join("").slice(0, 2).toUpperCase()}
135	                </AvatarFallback>
136	              </Avatar>
137	              <div className="flex-1 min-w-0">
138	                <div className="flex items-baseline justify-between gap-2 mb-0.5">
139	                  <span className="font-semibold text-sm truncate">{t.threadUserName}</span>
140	                  <span className="text-[10px] text-muted-foreground shrink-0">
141	                    {format(parseISO(last.createdAt), "HH:mm · dd MMM")}
142	                  </span>
143	                </div>
144	                <div className="text-xs text-muted-foreground truncate mb-0.5">{t.courtName}</div>
145	                {t.latestBooking && (
146	                  <div className="flex items-center gap-1 mb-0.5">
147	                    <Badge variant="outline" className="text-[10px] h-4 px-1.5 font-normal gap-1 border-primary/30 text-primary">
148	                      <Calendar className="w-2.5 h-2.5" />
149	                      {t.latestBooking.date} · {t.latestBooking.startTime}–{t.latestBooking.endTime}
150	                    </Badge>
151	                  </div>
152	                )}
153	                <div className="text-xs text-foreground/80 truncate">{last.body}</div>
154	              </div>
155	            </button>
156	          </li>
157	        );
158	      })}
159	    </ul>
160	  );
161	}
162	
163	function OwnerChatPane({
164	  thread,
165	  ownerUserId,
166	  ownerName,
167	  ownerEmail,
168	  onBack,
169	}: {
170	  thread: OwnerThread;
171	  ownerUserId: string;
172	  ownerName: string;
173	  ownerEmail: string;
174	  onBack: () => void;
175	}) {
176	  const queryClient = useQueryClient();
177	  const [text, setText] = useState("");
178	  const bottomRef = useRef<HTMLDivElement>(null);
179	
180	  const queryKey = messagesQueryKey(thread.courtId, thread.threadUserId);
181	
182	  const { data: msgs = [], isLoading } = useQuery<OwnerMsg[]>({
183	    queryKey,
184	    queryFn: () =>
185	      customFetch<OwnerMsg[]>(
186	        `${API_URL}/courts/${thread.courtId}/messages?userId=${encodeURIComponent(thread.threadUserId)}`,
187	      ),
188	  });
189	
190	  const sendMutation = useMutation({
191	    mutationFn: (body: string) =>
192	      customFetch<OwnerMsg>(`${API_URL}/courts/${thread.courtId}/messages`, {
193	        method: "POST",
194	        headers: { "Content-Type": "application/json" },
195	        body: JSON.stringify({
196	          senderUserId: ownerUserId,
197	          senderName: ownerName,
198	          senderEmail: ownerEmail,
199	          body,
200	          threadUserId: thread.threadUserId,
201	        }),
202	      }),
203	    onSuccess: (msg) => {
204	      queryClient.setQueryData<OwnerMsg[]>(queryKey, (prev) =>
205	        prev ? [...prev, msg] : [msg],
206	      );
207	      queryClient.invalidateQueries({ queryKey: ["owner-inbox"] });
208	      setText("");
209	    },
210	  });
211	
212	  useEffect(() => {
213	    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
214	  }, [msgs]);
215	
216	  const send = () => {
217	    const body = text.trim();
218	    if (!body || sendMutation.isPending) return;
219	    sendMutation.mutate(body);
220	  };
221	
222	  return (
223	    <div className="flex flex-col h-full min-h-0">
224	      <div className="flex items-start gap-3 px-4 py-3 border-b bg-card shrink-0">
225	        <button
226	          onClick={onBack}
227	          className="md:hidden text-muted-foreground hover:text-foreground mt-0.5"
228	          aria-label="Atgal"
229	        >
230	          <ArrowLeft className="w-5 h-5" />
231	        </button>
232	        <Avatar className="h-10 w-10 shrink-0">
233	          {thread.threadUserImageUrl && <AvatarImage src={thread.threadUserImageUrl} alt={thread.threadUserName} />}
234	          <AvatarFallback className="bg-primary/15 text-primary font-semibold text-xs">
235	            {thread.threadUserName.split(" ").map((n: string) => n[0]).join("").slice(0, 2).toUpperCase()}
236	          </AvatarFallback>
237	        </Avatar>
238	        <div className="min-w-0 flex-1">
239	          <p className="font-semibold text-sm leading-tight truncate">{thread.threadUserName}</p>
240	          <p className="text-xs text-muted-foreground truncate">{thread.courtName}</p>
241	          {thread.latestBooking && (
242	            <div className="flex items-center gap-1 mt-1">
243	              <Badge variant="outline" className="text-[10px] h-4 px-1.5 font-normal gap-1 border-primary/30 text-primary">
244	                <Calendar className="w-2.5 h-2.5" />
245	                Rez. #{thread.latestBooking.id} · {thread.latestBooking.date} {thread.latestBooking.startTime}–{thread.latestBooking.endTime}
246	              </Badge>
247	            </div>
248	          )}
249	        </div>
250	      </div>
251	      <div className="flex-1 overflow-y-auto px-4 py-3 space-y-3 min-h-0">
252	        {isLoading ? (
253	          <div className="space-y-3">
254	            {Array.from({ length: 4 }).map((_, i) => (
255	              <div
256	                key={i}
257	                className={`flex ${i % 2 === 0 ? "justify-start" : "justify-end"}`}
258	              >
259	                <Skeleton className="h-10 w-44 rounded-2xl" />
260	              </div>
261	            ))}
262	          </div>
263	        ) : msgs.length === 0 ? (
264	          <div className="flex flex-col items-center justify-center h-full text-muted-foreground text-sm gap-2">
265	            <MessageSquare className="w-10 h-10 opacity-20" />
266	            <p>Dar nėra žinučių šiame pokalbyje.</p>
267	          </div>
268	        ) : (
269	          msgs.map((msg) => {
270	            const isMine = msg.senderUserId === ownerUserId;
271	            return (
272	              <div
273	                key={msg.id}
274	                className={`flex ${isMine ? "justify-end" : "justify-start"}`}
275	              >
276	                <div
277	                  className={`max-w-[75%] flex flex-col gap-0.5 ${
278	                    isMine ? "items-end" : "items-start"
279	                  }`}
280	                >
281	                  {!isMine && (
282	                    <span className="text-[11px] text-muted-foreground px-1">
283	                      {msg.senderName}
284	                    </span>
285	                  )}
286	                  <div
287	                    className={`px-3.5 py-2 rounded-2xl text-sm ${
288	                      isMine
289	                        ? "bg-primary text-primary-foreground rounded-br-sm"
290	                        : "bg-muted text-foreground rounded-bl-sm"
291	                    }`}
292	                  >
293	                    {msg.body}
294	                  </div>
295	                  <span className="text-[10px] text-muted-foreground px-1">
296	                    {format(parseISO(msg.createdAt), "HH:mm · dd MMM")}
297	                  </span>
298	                </div>
299	              </div>
300	            );
301	          })
302	        )}
