36	    if (!existing) {
37	      threadMap.set(otherUserId, {
38	        otherUserId,
39	        otherUserName: r.senderUserId === userId ? "—" : r.senderName,
40	        lastMessage: formatMsg(r),
41	        unread: isUnread ? 1 : 0,
42	      });
43	    } else if (isUnread) {
44	      existing.unread += 1;
45	    }
46	  }
47	
48	  // Fill in names for threads where the latest message is from me
49	  for (const thread of threadMap.values()) {
50	    if (thread.otherUserName === "—") {
51	      const fromOther = rows.find(r => r.senderUserId === thread.otherUserId);
52	      if (fromOther) thread.otherUserName = fromOther.senderName;
53	      else thread.otherUserName = "Vartotojas";
54	    }
55	  }
56	
57	  // Fetch avatars for all other users from userProfilesTable
58	  const otherIds = [...threadMap.keys()];
59	  const imageMap = new Map<string, string | null>();
60	  if (otherIds.length > 0) {
61	    const profiles = await db
62	      .select({ userId: userProfilesTable.userId, imageUrl: userProfilesTable.imageUrl })
63	      .from(userProfilesTable)
64	      .where(inArray(userProfilesTable.userId, otherIds));
65	    for (const p of profiles) imageMap.set(p.userId, p.imageUrl);
66	  }
67	
68	  const threads = [...threadMap.values()].map(t => ({
69	    ...t,
70	    otherUserImageUrl: imageMap.get(t.otherUserId) ?? null,
71	  }));
72	
73	  res.json(threads);
74	});
