80	
81	  const rows = await db.select().from(directMessagesTable)
82	    .where(or(
83	      and(eq(directMessagesTable.senderUserId, userId), eq(directMessagesTable.recipientUserId, otherUserId)),
84	      and(eq(directMessagesTable.senderUserId, otherUserId), eq(directMessagesTable.recipientUserId, userId)),
85	    ))
86	    .orderBy(directMessagesTable.createdAt);
87	
88	  // Mark incoming messages as read
89	  await db.update(directMessagesTable).set({ readAt: new Date() })
90	    .where(and(
91	      eq(directMessagesTable.senderUserId, otherUserId),
92	      eq(directMessagesTable.recipientUserId, userId),
93	      sql`${directMessagesTable.readAt} IS NULL`,
94	    ));
95	
96	  res.json(rows.map(formatMsg));
