22	function playChime() {
23	  try {
24	    if (typeof window === "undefined") return;
25	    const AC = (window.AudioContext || (window as any).webkitAudioContext) as typeof AudioContext | undefined;
26	    if (!AC) return;
27	    if (!audioCtx) audioCtx = new AC();
28	    const ctx = audioCtx;
29	    const now = ctx.currentTime;
30	    const gain = ctx.createGain();
31	    gain.gain.setValueAtTime(0.0001, now);
32	    gain.gain.exponentialRampToValueAtTime(0.18, now + 0.015);
33	    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.45);
34	    gain.connect(ctx.destination);
35	    const notes = [880, 1175];
36	    notes.forEach((freq, i) => {
37	      const osc = ctx.createOscillator();
38	      osc.type = "sine";
39	      osc.frequency.setValueAtTime(freq, now + i * 0.08);
40	      osc.connect(gain);
41	      osc.start(now + i * 0.08);
42	      osc.stop(now + i * 0.08 + 0.25);
43	    });
44	  } catch { /* ignore */ }
45	}
