135	function timeAgo(iso: string) {
136	  const d = new Date(iso);
137	  const diff = Date.now() - d.getTime();
138	  const min = Math.floor(diff / 60000);
139	  if (min < 1) return "dabar";
140	  if (min < 60) return `${min}min`;
141	  const h = Math.floor(min / 60);
142	  if (h < 24) return `${h}h`;
143	  return d.toLocaleDateString("lt-LT", { month: "short", day: "numeric" });
144	}
