152	function useContextInfo(ctxType?: string, ctxId?: number): CtxInfo | null {
153	  const enabled = !!ctxType && !!ctxId;
154	  const { data } = useQuery<any>({
155	    queryKey: ["chat-ctx", ctxType, ctxId],
156	    queryFn: async () => {
157	      if (ctxType === "game") return customFetch<any>(`${API}/games/${ctxId}`);
158	      if (ctxType === "court") return customFetch<any>(`${API}/courts/${ctxId}`);
159	      if (ctxType === "facility") return customFetch<any>(`${API}/facilities/${ctxId}`);
160	      if (ctxType === "tournament") return customFetch<any>(`${API}/tournaments/${ctxId}`);
161	      if (ctxType === "booking") return customFetch<any>(`${API}/bookings/${ctxId}`).catch(() => null);
162	      return null;
163	    },
164	    enabled,
165	    staleTime: 60_000,
166	  });
167	  if (!enabled) return null;
168	  if (ctxType === "game") {
169	    const name = data?.sport ? `Žaidimas · ${data.city ?? ""}` : `Žaidimas #${ctxId}`;
170	    return { label: name, href: `/matches/${ctxId}`, Icon: UsersIcon };
171	  }
172	  if (ctxType === "court") {
173	    return { label: data?.name ? `Aikštelė · ${data.name}` : `Aikštelė #${ctxId}`, href: `/courts/${ctxId}`, Icon: MapPin };
174	  }
175	  if (ctxType === "facility") {
176	    return { label: data?.name ? `Centras · ${data.name}` : `Centras #${ctxId}`, href: `/courts?facility=${ctxId}`, Icon: Building2 };
